import java.io.*;

public class D1 {
    public static void main(String[] args) throws Exception {
        SimpleReader in = new SimpleReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        long n = in.nextLong();
        long m = in.nextLong();
        pw.println(solve(n, m));
        pw.close();
    }

    static long solve(long n, long m) {
        if (n > m) {
            long t = n; n = m; m = t;
        }
        if (n == 1) {
            long base = (m / 6) * 6;
            long rem = m % 6;
            if (rem == 4) base += 2;
            if (rem == 5) base += 4;
            return base;
        }
        if (n == 2) {
            if (m == 2) return 0;
            if (m == 3) return 4;
            if (m == 7) return 12;
        }
        long res = n * m;
        if (n % 2 == 1 && m % 2 == 1) res--;
        return res;
    }

    static class SimpleReader {
        private final Reader reader;

        SimpleReader(InputStream in) {
            reader = new InputStreamReader(in);
        }

        long nextLong() throws IOException {
            int b;
            do {
                b = reader.read();
            } while (b != -1 && !(b >= '0' && b <= '9' || b == '-'));
            if (b == -1) return 0L;
            boolean minus = false;
            if (b == '-') {
                minus = true;
                b = reader.read();
            }
            long num = 0;
            while (b != -1 && b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
                b = reader.read();
            }
            return minus ? -num : num;
        }
    }
}
